import React, { useState } from "react";
import axios from "axios";

function App() {
  const [file, setFile] = useState(null);
  const [language, setLanguage] = useState("en");
  const [loading, setLoading] = useState(false);
  const [data, setData] = useState(null);

  const handleUpload = async () => {
    if (!file) return alert("Upload audio file");

    const formData = new FormData();
    formData.append("file", file);
    formData.append("language", language);

    try {
      setLoading(true);
      const res = await axios.post(
        "http://127.0.0.1:8000/process-audio",
        formData
      );
      setData(res.data);
    } catch (err) {
      console.error(err);
      alert("Error processing audio");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen bg-gray-100 p-6">

      {/* Header */}
      <h1 className="text-3xl font-bold text-center mb-6">
        🏥 MedScript AI
      </h1>

      {/* Upload Card */}
      <div className="bg-white p-6 rounded-2xl shadow-md max-w-xl mx-auto">
        <input
          type="file"
          onChange={(e) => setFile(e.target.files[0])}
          className="mb-4"
        />

        <select
          value={language}
          onChange={(e) => setLanguage(e.target.value)}
          className="border p-2 rounded mb-4 w-full"
        >
          <option value="en">English</option>
          <option value="hi">Hindi</option>
        </select>

        <button
          onClick={handleUpload}
          className="bg-blue-600 text-white px-4 py-2 rounded w-full"
        >
          {loading ? "Processing..." : "Upload & Process"}
        </button>
      </div>

      {/* Results */}
      {data && (
        <div className="mt-8 max-w-4xl mx-auto space-y-6">

          {/* Summary */}
          <Card title="Summary">
            {data.summary}
          </Card>

          {/* SOAP Report */}
          <Card title="Subjective">
            {data.report.subjective?.map((s, i) => <li key={i}>{s}</li>)}
          </Card>

          <Card title="Objective">
            {data.report.objective?.map((o, i) => <li key={i}>{o}</li>)}
          </Card>

          <Card title="Assessment">
            {data.report.assessment}
          </Card>

          <Card title="Plan - Medicines">
            {data.report.plan?.medicines?.map((m, i) => <li key={i}>{m}</li>)}
          </Card>

          <Card title="Plan - Advice">
            {data.report.plan?.advice?.map((a, i) => <li key={i}>{a}</li>)}
          </Card>

          {/* Entities */}
          <Card title="Detected Symptoms">
            {data.entities.symptoms.map((s, i) => <li key={i}>{s}</li>)}
          </Card>

          <Card title="Detected Medicines">
            {data.entities.medicines.map((m, i) => <li key={i}>{m}</li>)}
          </Card>

          {/* Download */}
          <a
            href={`http://127.0.0.1:8000/download-report/${data.id}`}
            target="_blank"
            rel="noreferrer"
            className="block text-center bg-green-600 text-white p-3 rounded-xl"
          >
            Download PDF Report
          </a>

        </div>
      )}
    </div>
  );
}

const Card = ({ title, children }) => (
  <div className="bg-white p-5 rounded-2xl shadow">
    <h2 className="text-xl font-semibold mb-3">{title}</h2>
    <ul className="list-disc pl-5">{children}</ul>
  </div>
);

export default App;
